// Icons become Nerd Font glyphs in the desktop font, as everywhere in Omarchy.
//
// stremio-web renders each icon as an inline <svg> whose only identity is
// its paths, so an icon is recognized by the start of its first path
// (OMATRIMIO_ICONS, generated by scripts/build-icons.py). Its paths are
// hidden by the stylesheet and a <text> glyph is drawn in their place, in
// currentColor, so every color rule stremio-web has for its icons still
// applies. The paths stay in the DOM because React owns them; when React
// swaps an icon (outline to filled on the selected tab), it rewrites the
// path, and the glyph follows.
(() => {
    const SVG_NS = 'http://www.w3.org/2000/svg';
    const MARK = 'data-omatrimio-icon';
    const GLYPH = 'data-omatrimio-glyph';

    const glyphFor = (svg) => {
        const path = svg.querySelector(':scope > path');
        const d = path && path.getAttribute('d');
        return d ? OMATRIMIO_ICONS[d.slice(0, OMATRIMIO_ICON_FINGERPRINT)] : undefined;
    };

    const render = (svg) => {
        const code = glyphFor(svg);
        let text = svg.querySelector(`:scope > text[${GLYPH}]`);

        // An icon with no glyph (a brand logo) keeps Stremio's drawing.
        if (code === undefined) {
            text?.remove();
            svg.removeAttribute(MARK);
            return;
        }

        if (!text) {
            text = document.createElementNS(SVG_NS, 'text');
            text.setAttribute(GLYPH, '');
            text.setAttribute('text-anchor', 'middle');
            text.setAttribute('dominant-baseline', 'central');
            svg.appendChild(text);
        }

        const box = svg.viewBox.baseVal;
        const { x, y, width, height } = box && box.width ? box : { x: 0, y: 0, width: 24, height: 24 };
        text.setAttribute('x', x + width / 2);
        text.setAttribute('y', y + height / 2);
        // Inline, because stremio-web's font-size rules outrank the attribute
        // and would shrink the glyph to 14 units of a 512-unit drawing.
        text.style.setProperty('font-size', `${Math.min(width, height)}px`, 'important');

        const glyph = String.fromCodePoint(code);
        if (text.textContent !== glyph) text.textContent = glyph;
        svg.setAttribute(MARK, '');
    };

    const scan = (node) => {
        if (node.nodeType !== Node.ELEMENT_NODE || node.hasAttribute(GLYPH)) return;
        if (node.localName === 'svg') render(node);
        node.querySelectorAll('svg').forEach(render);
    };

    const observer = new MutationObserver((records) => {
        for (const record of records) {
            if (record.type === 'attributes') {
                const svg = record.target.closest('svg');
                if (svg) render(svg);
            } else {
                record.addedNodes.forEach(scan);
            }
        }
    });

    document.addEventListener('DOMContentLoaded', () => {
        scan(document.body);
        observer.observe(document.body, {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ['d'],
        });
    });
})();
